// Uses the local test manager and fixture GitLab metadata only.
const {chromium}=require('playwright');
const assert=require('node:assert/strict');
(async()=>{
 const browser=await chromium.launch({headless:true});
 try {
  const page=await browser.newPage({viewport:{width:1440,height:1000}}),errors=[];
  page.on('pageerror',e=>errors.push(e.message));
  await page.goto(process.argv[2]);
  await page.locator('#open-gitlab-source').click();
  if(await page.locator('#gitlab-events-settings').getAttribute('open')===null)await page.locator('#gitlab-events-summary').press('Enter');
  await page.locator('#gitlab-project-summary').waitFor({state:'visible'});
  assert.equal(await page.locator('#notification-manage-binding, #gitlab-events-project').count(),0);
  const connection=await page.locator('#gitlab-connection').inputValue();
  await page.locator('#gitlab-connection').selectOption('');
  await page.locator('#gitlab-project-hint').waitFor({state:'visible'});
  assert.equal(await page.locator('#gitlab-project-summary').textContent(),'请先选择平台连接');
  await page.locator('#gitlab-project-summary').click();
  assert.equal(await page.locator('#gitlab-project-picker').getAttribute('open'),null);
  await page.locator('#gitlab-events-fields').screenshot({path:'/tmp/teamx-project-connection-hint.png'});
  await page.locator('#gitlab-connection').selectOption(connection);
  await page.locator('#gitlab-project-hint').waitFor({state:'hidden'});
  await page.locator('#gitlab-project-summary').click();
  await page.locator('#gitlab-project-options input').waitFor();
  await page.locator('#gitlab-project-more').click();
  await page.waitForFunction(()=>document.querySelectorAll('#gitlab-project-options input').length===2);
  assert.equal(await page.locator('#gitlab-project-more').isVisible(),false);
  const row=page.locator('#gitlab-project-options label').first();
  const radio=await row.locator('input').boundingBox(),label=await row.locator('span').first().boundingBox();
  assert.ok(radio.width<=20 && label.width>=50 && label.x>=radio.x+radio.width,JSON.stringify({radio,label}));
  await page.screenshot({path:'/tmp/teamx-project-picker-desktop.png',fullPage:true});
  await page.locator('#gitlab-project-search').fill('fail');
  await page.locator('#gitlab-project-status').filter({hasText:'读取失败'}).waitFor();
  assert.equal(await page.locator('#gitlab-project-summary').textContent(),'remote/project');
  await page.locator('#gitlab-project-search').fill('missing');
  await page.locator('#gitlab-project-status').filter({hasText:'没有匹配'}).waitFor();
  await page.locator('#gitlab-project-search').fill('target');
  await page.locator('#gitlab-project-options input[value="remote/other"]').waitFor();
  await page.setViewportSize({width:390,height:844});
  await page.screenshot({path:'/tmp/teamx-project-picker-mobile.png',fullPage:true});
  const overflow=await page.locator('#gitlab-project-picker').evaluate(el=>el.scrollWidth>el.clientWidth+1);
  assert.equal(overflow,false);
  await page.locator('#gitlab-project-options input[value="remote/other"]').check();
  assert.equal(await page.locator('#gitlab-project-picker').getAttribute('open'),null);
  await page.locator('#gitlab-save').click();
  await page.locator('#gitlab-feedback').filter({hasText:'设置已保存'}).waitFor();
  assert.equal(await page.locator('#gitlab-project-summary').textContent(),'remote/other');
  await page.locator('#notification-tab-messages').click();
  await page.locator('#lark-enabled').check();
  await page.locator('#lark-chat-picker-hint').waitFor({state:'visible'});
  assert.equal(await page.locator('#lark-chat-picker-summary').textContent(),'请先选择平台连接');
  assert.equal(await page.locator('#lark-chat-search').isDisabled(),true);
  assert.equal(await page.locator('#lark-chat-type').isDisabled(),true);
  await page.locator('#lark-chat-picker-summary').click();
  assert.equal(await page.locator('#lark-chat-picker').getAttribute('open'),null);
  await page.locator('.lark-conversation-controls').screenshot({path:'/tmp/teamx-lark-chat-connection-hint.png'});
  assert.deepEqual(errors,[]);
  console.log(JSON.stringify({fixture_only:true,search:true,pagination:true,error_and_empty:true,selection_and_save:true,desktop:[1440,1000],mobile:[390,844],page_errors:0}));
 }finally{await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
